const network=navigator.connection||navigator.mozConnection||navigator.webkitConnection;if(network&&network.addEventListener)network.addEventListener('change',()=>{if(network.saveData||/^(slow-2g|2g)$/.test(network.effectiveType||'')||(network.downlink>0&&network.downlink<1))activateLightMode();});
