$('#language-select').onchange=e=>{localStorage.setItem('badreason-language',e.target.value);location.reload();};$('#palette-select').onchange=e=>{if(colorMode==='dark'){darkPalette=e.target.value;localStorage.setItem('badreason-dark-palette',darkPalette);}else{palette=e.target.value;localStorage.setItem('badreason-palette',palette);}applyAppearance();};
function settingsOpen(open,restore=false){$('#settings-panel').hidden=!open;$('#settings-toggle').setAttribute('aria-expanded',String(open));if(open)$('#language-select').focus();else if(restore)$('#settings-toggle').focus();}
$('#settings-toggle').onclick=()=>settingsOpen($('#settings-panel').hidden);$('#settings-close').onclick=()=>settingsOpen(false,true);
document.addEventListener('click',e=>{if(!e.target.closest('.settings-wrap'))settingsOpen(false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#settings-panel').hidden)settingsOpen(false,true);});
document.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{colorMode=button.dataset.mode;localStorage.setItem('badreason-mode',colorMode);applyAppearance();document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===colorMode)));$('#palette-select').innerHTML=(colorMode==='dark'?darkPalettes:palettes).map(([key,label])=>`<option value="${key}" ${key===(colorMode==='dark'?darkPalette:palette)?'selected':''}>${label}</option>`).join('');});$('#full-mode').onclick=()=>{lightMode=false;document.body.classList.remove('low-bandwidth');$('#network-note').hidden=true;sessionStorage.setItem('badreason-full-mode','1');};
try{if(sessionStorage.getItem('badreason-full-mode')==='1')lightMode=false;}catch{}document.body.classList.toggle('low-bandwidth',lightMode);if(lightMode){document.body.classList.add('low-bandwidth');$('#network-note').hidden=false;}
