 const draft=shippingDraft();const field=(name,label,attrs='',hint='')=>`<label class="field"><span>${label}</span><input name="${name}" value="${esc(draft[name]||'')}" ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;
