  if(params.has('cancel')){status.textContent='Cancelaste el pago. No se realizó ningún cobro.';paymentResult('fail','Pago cancelado.','<p>Puedes volver a intentarlo cuando quieras. Tu carrito sigue guardado.</p>',`<a class="button" href="/pago">Volver a intentar ${icon('arrow')}</a>`);return;}
